export const script = "\n    // Tab Switching Logic\n    function activateTab(btn, tabId) {\n      document.querySelectorAll('.tab-btn').forEach(el => {\n        el.classList.remove('bg-[#8468FF]', 'text-white', 'shadow-sm');\n        el.classList.add('text-[#9A9AA8]');\n        el.setAttribute('aria-selected', 'false');\n      });\n      btn.classList.add('bg-[#8468FF]', 'text-white', 'shadow-sm');\n      btn.classList.remove('text-[#9A9AA8]');\n      btn.setAttribute('aria-selected', 'true');\n\n      document.querySelectorAll('.tab-pane').forEach(panel => {\n        panel.classList.add('hidden');\n      });\n      const active = document.getElementById(tabId);\n      if (active) active.classList.remove('hidden');\n    }\n\n    function activateTabDirectly(tabId) {\n      const tabTargetBtn = Array.from(document.querySelectorAll('.tab-btn')).find(b => b.getAttribute('onclick').includes(tabId));\n      if (tabTargetBtn) {\n        activateTab(tabTargetBtn, tabId);\n      }\n    }\n\n    // Thumbnail Switcher\n    function switchThumb(thumbBtn, index) {\n      document.querySelectorAll('#tab-description button, .group button').forEach(b => {\n        b.classList.remove('ring-2', 'ring-[#8468FF]', 'opacity-100');\n        b.classList.add('opacity-60');\n      });\n      thumbBtn.classList.remove('opacity-60');\n      thumbBtn.classList.add('ring-2', 'ring-[#8468FF]', 'opacity-100');\n    }\n\n    // License Card Selection & Price Calculation\n    function updatePrice(val, name) {\n      const display = document.getElementById('displayPrice');\n      if (display) {\n        display.textContent = '$' + Number(val).toFixed(2);\n      }\n      // Update radio card ring styling\n      document.querySelectorAll('.license-card').forEach(card => {\n        const input = card.querySelector('input');\n        if (input && input.checked) {\n          card.classList.add('ring-2', 'ring-[#8468FF]');\n        } else {\n          card.classList.remove('ring-2', 'ring-[#8468FF]');\n        }\n      });\n    }\n\n    // Add to Cart Micro-Interaction\n    function handleAddToCart() {\n      const btn = document.getElementById('addToCartBtn');\n      const text = document.getElementById('addToCartText');\n      if (!btn || !text) return;\n      \n      const originalText = text.textContent;\n      text.textContent = 'Added to Cart!';\n      btn.classList.remove('bg-[#8468FF]');\n      btn.classList.add('bg-[#1FA971]');\n      \n      setTimeout(() => {\n        text.textContent = originalText;\n        btn.classList.remove('bg-[#1FA971]');\n        btn.classList.add('bg-[#8468FF]');\n      }, 2000);\n    }\n\n    // Bundle Cart Trigger\n    function addBundleToCart() {\n      handleAddToCart();\n    }\n\n    // Wishlist Toggle\n    function toggleWishlist(btn) {\n      const icon = btn.querySelector('.material-symbols-outlined');\n      if (icon) {\n        if (icon.style.fontVariationSettings && icon.style.fontVariationSettings.includes(\"'FILL' 1\")) {\n          icon.style.fontVariationSettings = \"'FILL' 0\";\n          btn.classList.remove('text-[#E5484D]');\n          btn.classList.add('text-[#9A9AA8]');\n        } else {\n          icon.style.fontVariationSettings = \"'FILL' 1\";\n          btn.classList.remove('text-[#9A9AA8]');\n          btn.classList.add('text-[#E5484D]');\n        }\n      }\n    }\n\n    // Follow Creator Toggle\n    function toggleFollow(btn) {\n      if (btn.innerText === '+ Follow') {\n        btn.innerText = 'Following';\n        btn.classList.add('bg-[#8468FF]', 'text-white');\n        btn.classList.remove('bg-[#1C1C26]');\n      } else {\n        btn.innerText = '+ Follow';\n        btn.classList.remove('bg-[#8468FF]', 'text-white');\n        btn.classList.add('bg-[#1C1C26]');\n      }\n    }\n\n    // Zoom Lightbox\n    function triggerZoomModal() {\n      const modal = document.getElementById('zoomModal');\n      if (modal) {\n        modal.classList.toggle('hidden');\n      }\n    }\n\n    // Close modal on escape\n    window.addEventListener('keydown', (e) => {\n      if (e.key === 'Escape') {\n        const modal = document.getElementById('zoomModal');\n        if (modal && !modal.classList.contains('hidden')) {\n          modal.classList.add('hidden');\n        }\n      }\n    });\n  ";
export const bodyClass = "bg-surface font-body-md text-on-surface antialiased";
